mapper.select:
SELECT COUNT(*)
  FROM CODE_MST
 WHERE CATEGORY = #{category}
   AND COMPANY_CODE = #{company_code}

mapper.insert:
INSERT INTO CODE_MST (
    CATEGORY, COMPANY_CODE, CATEGORY_NAME, CATEGORY_NAME_ENG, CATEGORY_NAME_LOC,
    CODE_LENGTH, UPDATE_YN, CREATE_DATE, CREATE_BY, UPDATE_DATE, UPDATE_BY
) VALUES (
    #{category}, #{company_code}, #{category_name}, NULLIF(#{category_name_eng}, ''),
    NULLIF(#{category_name_loc}, ''), #{code_length}, #{update_yn},
    NOW(), #{update_by}, NOW(), #{update_by}
)

mapper.update:
UPDATE CODE_MST
   SET CATEGORY_NAME = #{category_name}
     , CATEGORY_NAME_ENG = NULLIF(#{category_name_eng}, '')
     , CATEGORY_NAME_LOC = NULLIF(#{category_name_loc}, '')
     , CODE_LENGTH = #{code_length}
     , UPDATE_YN = #{update_yn}
     , UPDATE_DATE = NOW()
     , UPDATE_BY = #{update_by}
 WHERE CATEGORY = #{category}
   AND COMPANY_CODE = #{company_code}

UPDATE CODE_DTL
   SET DELETE_YN = 'Y'
     , USING_YN = 'N'
     , UPDATE_DATE = NOW()
     , UPDATE_BY = #{update_by}
 WHERE CATEGORY = #{category}
   AND COMPANY_CODE = #{company_code}
   AND DELETE_YN = 'N'

mapper.delete:
DELETE FROM CODE_DTL
 WHERE CATEGORY = #{category}
   AND COMPANY_CODE = #{company_code}

DELETE FROM CODE_MST
 WHERE CATEGORY = #{category}
   AND COMPANY_CODE = #{company_code}
